require_once __DIR__.'/../../core/db_connect.php'; require_once __DIR__.'/../../core/bible_studies.php';
header('Cache-Control: private, no-store');
$user=bs_require_eligible($pdo); $uid=(int)$user['id']; $message='';$error='';
if(!bs_schema_ready($pdo)){
    http_response_code(503);$page_title='General Bible Study';$page_styles=[BASE_PATH.'/assets/css/bible_study.css'];ob_start();
    ?><div class="bs-hero mb-4"><div><h1 class="h2 mb-1">General Bible Study</h1><p class="mb-0">Learn, reflect and grow together.</p></div></div><div class="alert alert-info" role="status"><h2 class="h5">Bible Study is being prepared</h2><p class="mb-0">This section is temporarily unavailable while setup is completed. Please try again shortly.</p></div><?php
    $content=ob_get_clean();include __DIR__.'/../portal/layout.php';exit;
}
try {
 if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
  bs_require_post();$action=$_POST['action']??'';$studyId=bs_positive_int($_POST['study_id']??null,'study');
  if($action==='register')bs_register($pdo,$studyId,bs_positive_int($_POST['session_id']??null,'session'),$uid);
  elseif($action==='cancel')bs_cancel_registration($pdo,$studyId,$uid);
  elseif($action==='save_note')bs_save_note($pdo,$studyId,$uid,trim((string)($_POST['note_content']??'')));
  else throw new InvalidArgumentException('Invalid action.');
  $message=$action==='save_note'?'Private note saved.':'Registration updated.';
 }
}catch(Throwable $e){error_log('[bible_study] '.$e->getMessage());$error=$e instanceof PDOException?'The request could not be completed.':$e->getMessage();}
$q=$pdo->query("SELECT b.id FROM bible_studies b WHERE b.status='published' AND b.study_date>=CURDATE() ORDER BY b.study_date LIMIT 1");$studyId=(int)$q->fetchColumn();$study=$studyId?bs_study($pdo,$studyId):null;
$sessions=$study?array_values(array_filter(bs_sessions($pdo,$studyId),static fn(array $session):bool=>(int)$session['is_active']===1)):[];$registration=$study?bs_active_registration($pdo,$studyId,$uid):null;$window=$study?bs_registration_window($study):null;
$materials=[];$note='';if($study){$q=$pdo->prepare('SELECT id,material_title,description,original_filename,file_size FROM bible_study_materials WHERE bible_study_id=? AND is_published=1 ORDER BY created_at');$q->execute([$studyId]);$materials=$q->fetchAll();$q=$pdo->prepare('SELECT note_content FROM bible_study_notes WHERE bible_study_id=? AND member_user_id=?');$q->execute([$studyId,$uid]);$note=(string)($q->fetchColumn()?:'');}
$q=$pdo->prepare("SELECT b.study_date,b.title,b.status,r.status registration_status,s.session_name,a.attendance_status FROM bible_study_registrations r JOIN bible_studies b ON b.id=r.bible_study_id JOIN bible_study_sessions s ON s.id=r.session_id LEFT JOIN bible_study_attendance a ON a.registration_id=r.id WHERE r.member_user_id=? AND (b.study_date<CURDATE() OR b.status IN ('completed','cancelled','archived')) ORDER BY b.study_date DESC LIMIT 25");$q->execute([$uid]);$history=$q->fetchAll();
$page_title='General Bible Study';$page_styles=[BASE_PATH.'/assets/css/bible_study.css'];ob_start();
