<section class="card shadow-sm mb-4"><div class="card-body p-3 p-md-4"><div class="d-flex flex-wrap justify-content-between gap-2"><div><span class="badge bg-success"><?=escape(ucfirst($study['status']))?></span><h2 class="h3 mt-2 mb-1"><?=escape($study['title'])?></h2></div><div class="text-md-end"><strong><?=escape(date('l, j F Y',strtotime($study['study_date'])))?></strong><div class="text-muted">Leader: <?=escape($study['leader_name']?:'To be announced')?></div></div></div><hr><dl class="row mb-0"><dt class="col-sm-3">Scripture</dt><dd class="col-sm-9"><?=escape($study['primary_scripture'])?><?php if($study['additional_scriptures']):?><br><small><?=nl2br(escape($study['additional_scriptures']))?></small><?php endif;?></dd><dt class="col-sm-3">Prepare</dt><dd class="col-sm-9"><?=nl2br(escape($study['preparation_instructions']))?></dd><dt class="col-sm-3">Deadline</dt><dd class="col-sm-9"><?=escape(date('j M Y, H:i',strtotime($study['registration_deadline'])))?> EAT</dd></dl></div></section>
<?php if($window):?><div class="alert alert-info"><?=escape($window)?></div><?php endif;?>
<div class="row g-3 mb-4"><?php foreach($sessions as $s):$full=$s['capacity']!==null&&(int)$s['registered_count']>=(int)$s['capacity'];$selected=$registration&&(int)$registration['session_id']===(int)$s['id'];?><div class="col-12 col-md-4"><article class="card h-100 session-card <?=$selected?'selected':''?>"><div class="card-body"><div class="d-flex justify-content-between"><h3 class="h5"><?=escape($s['session_name'])?></h3><?php if($selected):?><span class="badge bg-primary">Selected</span><?php endif;?></div><p class="mb-2"><i class="bi bi-clock"></i> <?=escape(substr($s['start_time'],0,5))?>–<?=escape(substr($s['end_time'],0,5))?></p><p class="small text-muted"><?=$s['capacity']===null?'Unlimited capacity':escape((string)max(0,(int)$s['capacity']-(int)$s['registered_count'])).' places remaining'?></p><?php if(!$window&&!$full&&!$selected):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="register"><input type="hidden" name="study_id" value="<?=$studyId?>"><input type="hidden" name="session_id" value="<?=(int)$s['id']?>"><button class="btn btn-primary w-100"><?=$registration?'Change to this session':'Select session'?></button></form><?php elseif($full&&!$selected):?><button class="btn btn-secondary w-100" disabled>Full</button><?php endif;?></div></article></div><?php endforeach;?></div>
<?php if($registration&&!$window):?><form method="post" class="mb-4"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="study_id" value="<?=$studyId?>"><button class="btn btn-outline-danger" onclick="return confirm('Cancel your registration?')">Cancel registration</button></form><?php endif;?>
<div class="row g-4"><div class="col-lg-6"><section class="card h-100"><div class="card-body"><h2 class="h5">Study materials</h2><?php if(!$materials):?><p class="text-muted">No materials have been published.</p><?php else:?><ul class="list-group list-group-flush"><?php foreach($materials as $m):?><li class="list-group-item px-0"><a href="bible_study_download.php?material_id=<?=(int)$m['id']?>"><?=escape($m['material_title'])?></a><small class="d-block text-muted"><?=escape($m['original_filename'])?></small></li><?php endforeach;?></ul><?php endif;?></div></section></div><div class="col-lg-6"><section class="card h-100"><div class="card-body"><h2 class="h5">My private notes</h2><p class="small text-muted">Only you can view these notes.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_note"><input type="hidden" name="study_id" value="<?=$studyId?>"><label class="visually-hidden" for="note_content">Private notes</label><textarea class="form-control mb-2" id="note_content" name="note_content" maxlength="10000" rows="6"><?=escape($note)?></textarea><button class="btn btn-primary">Save notes</button></form></div></section></div></div>
<?php endif;?>
<section class="mt-4"><h2 class="h4">Previous studies and attendance</h2><?php if(!$history):?><p class="text-muted">No study history yet.</p><?php else:?><div class="list-group"><?php foreach($history as $h):?><div class="list-group-item d-flex flex-wrap justify-content-between"><span><strong><?=escape($h['title'])?></strong> · <?=escape($h['session_name'])?></span><span><?=escape($h['study_date'])?> · <?=escape($h['attendance_status']?:'not recorded')?></span></div><?php endforeach;?></div><?php endif;?></section>
